
import base64
import marshal
import zlib
import sys
import hashlib

_data = ""
_key = "po/TEHKxVPFHyUV65/gti5BuFCCunEFekFVYhe/pCAE="
_hash = "023a6a3ba0f03d9d"

def _decrypt(data, key):
    """XOR Decrypt"""
    return bytes([data[i] ^ key[i % len(key)] for i in range(len(data))])

def _verify(key, expected_hash):
    """Key Verification"""
    actual_hash = hashlib.sha256(key).hexdigest()[:16]
    return actual_hash == expected_hash

try:
 
    _k = base64.b64decode(_key)
    _d = base64.b64decode(_data)

    
    if not _verify(_k, _hash):
        print("Error: Invalid key")
        sys.exit(1)

    
    _x = _decrypt(_d, _k)
    _c = zlib.decompress(_x)
    _m = marshal.loads(_c)

    
    exec(_m)

except Exception as e:
    print(f"Error: {e}")
    sys.exit(1)
